import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { submitRationaleHandler } from "../handlers/submitRationaleHandler";
import type { ApiError } from "../runtime/client";
import type { FactFoldRoundEntityType } from "../types/FactFoldRoundEntityType";
import type { SubmitRationaleRequest } from "../types/SubmitRationaleRequest";

type Data = Awaited<ReturnType<typeof submitRationaleHandler>>;
type Vars = { roundId: FactFoldRoundEntityType; req: SubmitRationaleRequest };

export function useSubmitRationale(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => submitRationaleHandler(vars.roundId, vars.req),
    ...options,
  });
}
